def __init__(
    self,
    *args: ImmutableMultiDict[typing.Any, typing.Any]
    | typing.Mapping[typing.Any, typing.Any]
    | list[tuple[typing.Any, typing.Any]]
    | str
    | bytes,
    **kwargs: typing.Any,
) -> None:
    assert len(args) < 2, "Too many arguments."

    value = args[0] if args else []

    if isinstance(value, str):
        parsed = parse_qsl(value, keep_blank_values=True)
        # Convert to list of tuples with string keys and values
        self._list = [(str(k), str(v)) for k, v in parsed]
        # Build dict with last value for each key
        self._dict = {}
        for k, v in self._list:
            self._dict[k] = v
    elif isinstance(value, bytes):
        parsed = parse_qsl(value.decode("latin-1"), keep_blank_values=True)
        # Convert to list of tuples with string keys and values
        self._list = [(str(k), str(v)) for k, v in parsed]
        # Build dict with last value for each key
        self._dict = {}
        for k, v in self._list:
            self._dict[k] = v
    else:
        super().__init__(*args, **kwargs)
        self._list = [(str(k), str(v)) for k, v in self._list]
        self._dict = {str(k): str(v) for k, v in self._dict.items()}
